WITH src AS (
 SELECT x.*,md5('fbmn:long-an-old:wave02:'||x.source_key) digest
 FROM jsonb_to_recordset('[{"district":"Huyện Châu Thành","name":"Nhà sách Châu Thành (Tầm Vu)","address_line":"287 Tỉnh lộ 21, thị trấn Tầm Vu cũ, huyện Châu Thành","category":"nha_sach","phone":"02723671939","tax_code":null,"source_key":"gmap:ChIJB96UbpKzCjER3rT1PVdcenc","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20S%C3%A1ch%20Ch%C3%A2u%20Th%C3%A0nh%20T%E1%BA%A7m%20Vu%20Long%20An&query_place_id=ChIJB96UbpKzCjER3rT1PVdcenc","verification_note":"Bản đồ ghi 287 TL21; KHÔNG gán MST 1100112728-024 ở 287C TL837 vì MST đã đóng năm 2015. Cần xác minh tên/địa chỉ thực tế."},{"district":"Huyện Châu Thành","name":"Nhà sách Châu Thành - LABOCO","address_line":"210 Tỉnh lộ 827, khóm 1, thị trấn Tầm Vu cũ, huyện Châu Thành","category":"nha_sach","phone":null,"tax_code":"1100112728008","source_key":"tax:1100112728-008","source_url":"https://infodoanhnghiep.com/thong-tin/CN-Cong-ty-CP-Sach-Dich-vu-Van-Hoa-Long-An-Nha-sach-Chau-Thanh-12728-008.html","verification_note":"Hồ sơ chi nhánh còn hiển thị đang hoạt động nhưng là dữ liệu đăng ký; Nhà sách Châu Thành có điểm Maps khác địa chỉ, cần xác minh có thực sự hai quầy."},{"district":"Huyện Châu Thành","name":"Cửa hàng Sách - Thiết bị giáo dục Châu Thành","address_line":"52A Tỉnh lộ 827A, thị trấn Tầm Vu cũ, huyện Châu Thành","category":"nha_sach","phone":"02723503747","tax_code":null,"source_key":"official:nxbgd-2025-2026-chau-thanh-52a","source_url":"https://nxbgd.vn/Attachments/files/PDF/He%20thong%20cua%20hang%20toan%20quoc%202025-2026.pdf","verification_note":"Theo danh sách NXB Giáo dục 2025-2026, trang 15. Hồ sơ chi nhánh 1102045530-002 cùng tuyến đường nhưng chưa chắc trùng số nhà, chưa gán MST."},{"district":"Huyện Châu Thành","name":"Nhà sách Anh Khoa","address_line":"186 Tỉnh lộ 21, thị trấn Tầm Vu cũ, huyện Châu Thành","category":"nha_sach","phone":"02723877195","tax_code":null,"source_key":"gmap:ChIJL10HcIyzCjER_M6kTcsMAc0","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A